import {Trace} from './trace.mjs';
const main=(lines,defs='',headers='#include <stdio.h>')=>`${headers}\n${defs}\nint main(void)\n{\n${lines.map(l=>'    '+l).join('\n')}\n    return (0);\n}`;
const listDefs='typedef struct s_node\n{\n    int data;\n    struct s_node *next;\n} t_node;';
function setupList(b){b.step('t_node second = {2, NULL};','Create the last node','Create a struct holding data 2 and a NULL next link.','A node groups data and a link; NULL marks the end.','2 and NULL → second',()=>{b.cell('second','second','t_node',0x1100,'{data: 2, next: NULL}');b.state.world={kind:'list',head:'second',nodes:[{id:'second',data:2,next:null,address:'0x1100'}]};});b.step('t_node first = {1, &second};','Create the first node','Create first with data 1 and the address of second as its link.','List order follows next addresses rather than physical adjacency.','&second → first.next',()=>{b.cell('first','first','t_node',0x1000,'{data: 1, next: 0x1100}');b.state.world.head='first';b.state.world.nodes.unshift({id:'first',data:1,next:'second',address:'0x1000'});});}
function listWalk(){const b=new Trace('list-walk','Linked list · follow next until NULL','Traverse nodes using stored links, reading each node once.',main(['t_node second = {2, NULL};','t_node first = {1, &second};','t_node *cur = &first;','int count = 0;','while (cur != NULL)','{','    printf("%d ", cur->data);','    count++;','    cur = cur->next;','}','printf("count=%d\\n", count);'],listDefs));setupList(b);b.step('t_node *cur = &first;','Start at the head','Copy first’s address into cur.','Moving cur later will not move or copy a node.','&first → cur',()=>b.ptr('cur','cur','t_node *',0x2000,'first'));b.step('int count = 0;','Initialize the count','Set count to zero.','Each visited node will contribute one.','0 → count',()=>b.cell('count','count','int',0x2008,0));for(const [index,id]of ['first','second'].entries()){b.step('while (cur != NULL)','Check for a node','cur holds a valid node address.','Do not access cur->data after cur becomes NULL.','non-NULL → visit',()=>{},['cur']);b.step('printf("%d ", cur->data);','Read this node’s data',`Follow cur to ${id} and print ${index+1}.`,'The node is read without changing its link.','cur → node.data → terminal',()=>b.state.output+=`${index+1} `,['cur',id],[id]);b.step('count++;','Count the visit',`Increase count to ${index+1}.`,'Only the count changes.','count + 1 → count',()=>b.set('count',index+1));b.step('cur = cur->next;','Follow the next link',id==='first'?'Read first.next and copy second’s address into cur.':'Read second.next and copy NULL into cur.','Updating a traversal pointer does not alter the list links.','current node.next → cur',()=>{if(id==='first')b.ptr('cur','cur','t_node *',0x2000,'second');else{b.set('cur','NULL');delete b.state.cells.cur.target;}},['cur',id]);}b.step('while (cur != NULL)','Reach the end','cur is NULL, so the condition is false.','Two nodes were visited.','NULL → stop',()=>{},['cur']);return b.finish('printf("count=%d\\n", count);','count=2\n');}
function listInsert(){const b=new Trace('list-insert','Linked list · change the head via **','Preserve the old head before installing a new front node.',main(['t_node second = {2, NULL};','t_node first = {1, &second};','t_node *head = &first;','t_node added = {0, NULL};','t_node **out = &head;','added.next = *out;','*out = &added;','printf("%d %d %d\\n", head->data, head->next->data, head->next->next->data);'],listDefs));setupList(b);b.step('t_node *head = &first;','Create the head pointer','head points to first.','Changing head changes where traversal starts.','&first → head',()=>b.ptr('head','head','t_node *',0x2000,'first'));b.step('t_node added = {0, NULL};','Create the new node','Create added with data 0 and no next node yet.','This concept example uses a local node; an allocated node follows the same link mechanism but also needs allocation ownership.','new data → added',()=>{b.cell('added','added','t_node',0x1200,'{data: 0, next: NULL}');b.state.world.nodes.push({id:'added',data:0,next:null,address:'0x1200'});});b.step('t_node **out = &head;','Refer to the head object','out stores the address of head.','One dereference reaches the head pointer; another would reach its first node.','&head → out',()=>b.ptr('out','out','t_node **',0x2010,'head'));b.step('added.next = *out;','Preserve the existing chain','Read the pointer in head through out and put that address into added.next.','The old nodes stay reachable through the new node’s next link.','old head address → added.next',()=>{b.set('added','{data: 0, next: 0x1000}');b.state.world.nodes.find(n=>n.id==='added').next='first';},['out','head']);b.step('*out = &added;','Install the new head','Follow out and write added’s address into head.','head changes; the earlier first and second nodes do not move.','&added → *out → head',()=>{b.ptr('head','head','t_node *',0x2000,'added');b.state.world.head='added';},['out'],['head','added']);return b.finish('printf("%d %d %d\\n", head->data, head->next->data, head->next->next->data);','0 1 2\n');}
function listReverse(){const b=new Trace('list-reverse','Linked list · reverse links safely','Save next before overwriting it, then move the three traversal pointers.',main(['t_node second = {2, NULL};','t_node first = {1, &second};','t_node *cur = &first;','t_node *prev = NULL;','t_node *next;','while (cur != NULL)','{','    next = cur->next;','    cur->next = prev;','    prev = cur;','    cur = next;','}','printf("%d %d\\n", prev->data, prev->next->data);'],listDefs));setupList(b);b.step('t_node *cur = &first;','Start at the head','cur points to first.','The traversal will consume the original links.','&first → cur',()=>b.ptr('cur','cur','t_node *',0x2000,'first'));b.step('t_node *prev = NULL;','Start the reversed part empty','Initialize prev to NULL.','It will become the head of the completed reversed prefix.','NULL → prev',()=>b.cell('prev','prev','t_node *',0x2008,'NULL'));b.step('t_node *next;','Create a link backup','Reserve next without an initial value.','Always save the next link before changing a node’s link.','next created',()=>b.cell('next','next','t_node *',0x2010,undefined));for(const id of ['first','second']){const next=id==='first'?'second':null,prev=id==='first'?null:'first';b.step('while (cur != NULL)','Check the remaining original chain','cur is not NULL.','One node will be moved to the reversed prefix.','true → body',()=>{},['cur']);b.step('next = cur->next;','Save the original next address',next?'Save second’s address.':'Save NULL from the original final link.','After overwriting cur->next, this saved address is the only route to the remaining original chain.','cur.next → next',()=>{if(next)b.ptr('next','next','t_node *',0x2010,next);else{b.set('next','NULL');delete b.state.cells.next.target;}},['cur',id]);b.step('cur->next = prev;','Reverse this link',`Set ${id}.next to ${prev||'NULL'}.`,'The node’s data remains unchanged. Only the connection changes.','prev → node.next',()=>{b.set(id,`{data: ${id==='first'?1:2}, next: ${prev?'0x1000':'NULL'}}`);b.state.world.nodes.find(n=>n.id===id).next=prev;},['cur','prev']);b.step('prev = cur;','Extend the reversed prefix',`Copy ${id}’s address into prev.`,'prev now points to the head of the reversed prefix.','cur address → prev',()=>{b.ptr('prev','prev','t_node *',0x2008,id);b.state.world.head=id;},['cur']);b.step('cur = next;','Advance using the saved link',next?'Move cur to second.':'Set cur to NULL.','The saved original link lets traversal continue safely.','saved next → cur',()=>{if(next)b.ptr('cur','cur','t_node *',0x2000,next);else{b.set('cur','NULL');delete b.state.cells.cur.target;}},['next']);}b.step('while (cur != NULL)','End the reversal','cur is NULL.','prev is the new head: second → first → NULL.','false → stop',()=>{},['cur']);return b.finish('printf("%d %d\\n", prev->data, prev->next->data);','2 1\n');}
function listRemove(){const b=new Trace('list-remove','Linked list · bypass a node','A removed node must be unlinked before its storage is released.',main(['t_node *second = malloc(sizeof(*second));','t_node *first = malloc(sizeof(*first));','if (first == NULL || second == NULL)','{','    free(first);','    free(second);','    return (1);','}','second->data = 2;','second->next = NULL;','first->data = 1;','first->next = second;','first->next = second->next;','free(second);','second = NULL;','printf("%d %s\\n", first->data, first->next == NULL ? "end" : "more");','free(first);','first = NULL;'],listDefs,'#include <stdio.h>\n#include <stdlib.h>'));for(const [id,loc,pLoc]of [['second',0x5100,0x2000],['first',0x5000,0x2008]])b.step(`t_node *${id} = malloc(sizeof(*${id}));`,'Allocate a node',`Allocate enough space for ${id} and store its address in the pointer.`,'This trace follows successful allocation; fields are not initialized yet.','heap node address → pointer',()=>{b.cell(id+'obj',id+' node','t_node',loc,'uninitialized fields','heap');b.ptr(id,id,'t_node *',pLoc,id+'obj');});b.step('if (first == NULL || second == NULL)','Check both allocations','Both returned valid addresses, so the error branch is skipped.','The source frees any successful allocation on the failure path.','non-NULL pointers → continue',()=>{},['first','second']);for(const [at,id,val]of [['second->data = 2;','secondobj','{data: 2, next: uninitialized}'],['second->next = NULL;','secondobj','{data: 2, next: NULL}'],['first->data = 1;','firstobj','{data: 1, next: uninitialized}'],['first->next = second;','firstobj','{data: 1, next: 0x5100}']])b.step(at,'Initialize a node field','Write the specified data or link into the allocated node.','Do not read uninitialized fields. After these writes both nodes are complete.','field value → node',()=>{b.set(id,val);if(at==='first->next = second;')b.state.world={kind:'list',head:'first',nodes:[{id:'first',data:1,next:'second',address:'0x5000'},{id:'second',data:2,next:null,address:'0x5100'}]};});b.step('first->next = second->next;','Bypass the removed node','Read second.next, which is NULL, and write it into first.next.','The list no longer reaches second. Its allocated storage still exists until free.','second.next → first.next',()=>{b.set('firstobj','{data: 1, next: NULL}');b.state.world.nodes[0].next=null;},['first','second','secondobj']);b.step('free(second);','Release the unlinked node','Free the storage reached through second.','Dereferencing the old second address would now be invalid.','node storage released',()=>{delete b.state.cells.secondobj;delete b.state.cells.second.target;b.state.cells.second.invalid=true;b.state.world.nodes=b.state.world.nodes.filter(n=>n.id!=='second');},['second']);b.step('second = NULL;','Clear the expired address','Initialize second to NULL.','The surviving list has one node.','NULL → second',()=>{b.set('second','NULL');b.state.cells.second.invalid=false;});b.step('printf("%d %s\\n", first->data, first->next == NULL ? "end" : "more");','Read the surviving list','Print the remaining data and end marker.','first.next is NULL after the bypass.','1 end → terminal',()=>b.state.output+='1 end\n');b.step('free(first);','Release the final node','Free the remaining allocated node.','No heap node remains owned by this example.','last node released',()=>{delete b.state.cells.firstobj;delete b.state.cells.first.target;b.state.cells.first.invalid=true;b.state.world={kind:'list',head:null,nodes:[]};},['first']);b.step('first = NULL;','Clear the final pointer','Set first to NULL.','The example leaves no allocated node behind.','NULL → first',()=>{b.set('first','NULL');b.state.cells.first.invalid=false;});return b.finish('return (0);','');}
const treeDefs='typedef struct s_tree\n{\n    int data;\n    struct s_tree *left;\n    struct s_tree *right;\n} t_tree;';
function tree(mode){const order=mode==='prefix'?['print','left','right']:mode==='infix'?['left','print','right']:['left','right','print'],body=order.map(a=>a==='print'?'    printf("%d ", node->data);':`    visit(node->${a});`),defs=`${treeDefs}\nvoid visit(t_tree *node)\n{\n    if (node == NULL)\n        return;\n${body.join('\n')}\n}`,b=new Trace('tree-'+mode,`Binary tree · ${mode} traversal`,'Recursive calls visit a node and its two subtrees in a specified order.',main(['t_tree left = {1, NULL, NULL};','t_tree right = {3, NULL, NULL};','t_tree root = {2, &left, &right};','visit(&root);',"putchar('\\n');"],defs));const nodes={left:{data:1,left:null,right:null},right:{data:3,left:null,right:null},root:{data:2,left:'left',right:'right'}};for(const [id,loc]of [['left',0x1000],['right',0x1100],['root',0x1200]])b.step(`t_tree ${id} = {${id==='root'?'2, &left, &right':`${nodes[id].data}, NULL, NULL`}};`,'Create '+id,`Initialize ${id} and its child links.`,'These local nodes demonstrate structure and visitation. Allocating a node uses the separate malloc ownership lesson.','data and links → node',()=>{b.cell(id,id,'t_tree',loc,`{data: ${nodes[id].data}, left: ${nodes[id].left||'NULL'}, right: ${nodes[id].right||'NULL'}}`);if(!b.state.world)b.state.world={kind:'tree',root:'root',nodes:[]};b.state.world.nodes.push({id,...nodes[id],address:b.state.cells[id].address});});b.step('visit(&root);','Start at the root','Pass the root node’s address to visit.','Each recursive call has a separate node parameter.','&root → visit');let serial=0;function walk(id){const k=serial++,scope='visit '+(id||'NULL')+' #'+k;b.enter(scope);if(id)b.ptr('p'+k,'node','t_tree *',0x3000+k*8,id,scope);else b.cell('p'+k,'node','t_tree *',0x3000+k*8,'NULL',scope);b.capture(b.code.findIndex(l=>l==='void visit(t_tree *node)')+1,'Enter visit('+ (id||'NULL')+')','Copy the child address into this call’s node parameter.','The caller pauses while this child call executes.','address value → local node',[],id?[id]:[]);b.step('if (node == NULL)','Check for an empty subtree',id?'node refers to a real node; continue.':'node is NULL; return immediately.','Never access fields of a NULL node.','NULL test → '+!id,()=>{},['p'+k]);if(!id)b.step('return;','Return from the empty subtree','No node exists here, so there is no output.','This is the recursion base case.','return → parent');else for(const part of order){if(part==='print')b.step('printf("%d ", node->data);','Visit this node',`Print ${nodes[id].data} from ${id}.`,'The current node is highlighted in the tree.','node.data → terminal',()=>b.state.output+=nodes[id].data+' ',['p'+k,id],[id]);else{b.step(`visit(node->${part});`,'Visit the '+part+' subtree',`Read ${id}.${part} and pass that child address.`,'A NULL link also makes a call, which stops at the base case.','child link → recursive parameter',()=>{},['p'+k,id],[id]);walk(nodes[id][part]);}}b.leave();}walk('root');return b.finish("putchar('\\n');",'\n');}
function treeSearch(){const defs=treeDefs,b=new Trace('tree-search','Search tree · choose a branch','In a binary search tree, comparisons can skip a whole subtree.',main(['t_tree left = {1, NULL, NULL};','t_tree right = {3, NULL, NULL};','t_tree root = {2, &left, &right};','t_tree *cur = &root;','int target = 3;','while (cur != NULL && cur->data != target)','{','    if (target < cur->data)','        cur = cur->left;','    else','        cur = cur->right;','}','printf("%s\\n", cur == NULL ? "not found" : "found");'],defs));for(const [id,data,loc]of [['left',1,0x1000],['right',3,0x1100],['root',2,0x1200]])b.step(`t_tree ${id} = {${id==='root'?'2, &left, &right':`${data}, NULL, NULL`}};`,'Create '+id,'Initialize this node’s value and child links.','This tree follows the left-smaller, right-greater ordering.','node created',()=>{b.cell(id,id,'t_tree',loc,`{data: ${data}, left: ${id==='root'?'left':'NULL'}, right: ${id==='root'?'right':'NULL'}}`);if(!b.state.world)b.state.world={kind:'tree',root:'root',nodes:[]};b.state.world.nodes.push({id,data,left:id==='root'?'left':null,right:id==='root'?'right':null,address:b.state.cells[id].address});});b.step('t_tree *cur = &root;','Start at root','cur receives root’s address.','We will move a pointer without changing tree nodes.','&root → cur',()=>b.ptr('cur','cur','t_tree *',0x2000,'root'));b.step('int target = 3;','Create the search key','Set target to 3.','The key is compared with each encountered node’s data.','3 → target',()=>b.cell('target','target','int',0x2008,3));b.step('while (cur != NULL && cur->data != target)','Check the current node','cur is valid and root’s 2 differs from 3.','The left test protects the later dereference by short-circuiting when cur is NULL.','valid, unequal → continue',()=>{},['cur','root','target'],['root']);b.step('if (target < cur->data)','Choose a side','3 < 2 is false; choose the right link.','The entire left subtree is skipped because all of its keys are smaller.','false → right',()=>{},['target','root']);b.step('cur = cur->right;','Follow the right child','Copy root.right into cur.','The tree links stay unchanged; the search pointer moves.','root.right → cur',()=>b.ptr('cur','cur','t_tree *',0x2000,'right'),['root'],['right']);b.step('while (cur != NULL && cur->data != target)','Find the target','right.data is 3, equal to target; the condition is false.','cur retains the matching node’s address.','equal → stop',()=>{},['cur','right','target'],['right']);return b.finish('printf("%s\\n", cur == NULL ? "not found" : "found");','found\n');}
function argvSort(){const b=new Trace('argv-sort','Sort string pointers · swap addresses','Reordering a pointer array does not move or copy its string characters.',main(['char red[] = "red";','char blue[] = "blue";','char *items[2] = {red, blue};','char *tmp;','if (strcmp(items[0], items[1]) > 0)','{','    tmp = items[0];','    items[0] = items[1];','    items[1] = tmp;','}','printf("%s %s\\n", items[0], items[1]);'],'','#include <stdio.h>\n#include <string.h>'));b.step('char red[] = "red";','Create red','Initialize red and zero.','String contents will stay in these cells.','chars → red',()=>b.chars('r','red',0x1000,'red'));b.step('char blue[] = "blue";','Create blue','Initialize blue and zero.','These chars live separately from the pointer array.','chars → blue',()=>b.chars('b','blue',0x1100,'blue'));b.step('char *items[2] = {red, blue};','Create two address slots','Initialize items[0] with red’s first address and items[1] with blue’s.','This array stores pointers. Its element type is char *.','string addresses → items',()=>{b.ptr('p0','items[0]','char *',0x2000,'r0');b.ptr('p1','items[1]','char *',0x2008,'b0');});b.step('char *tmp;','Create a temporary address slot','Reserve tmp without initialization.','The swap will preserve one address, rather than a character.','tmp created',()=>b.cell('tmp','tmp','char *',0x2010,undefined));b.step('if (strcmp(items[0], items[1]) > 0)','Compare the pointed strings','red sorts after blue, so the comparison is positive.','The comparison reads characters through the two pointers; it does not compare raw address numbers.','string comparison → swap',()=>{},['p0','p1']);b.step('tmp = items[0];','Save the first address','Copy red’s address into tmp.','The red characters stay where they are.','items[0] address → tmp',()=>b.ptr('tmp','tmp','char *',0x2010,'r0'),['p0']);b.step('items[0] = items[1];','Move blue’s address left','Copy blue’s address into items[0].','Both pointer slots briefly refer to blue. tmp preserves red’s address.','items[1] address → items[0]',()=>b.ptr('p0','items[0]','char *',0x2000,'b0'),['p1']);b.step('items[1] = tmp;','Restore red’s address on the right','Copy red’s saved address into items[1].','Only pointer values changed. The strings were never copied.','tmp address → items[1]',()=>b.ptr('p1','items[1]','char *',0x2008,'r0'),['tmp']);return b.finish('printf("%s %s\\n", items[0], items[1]);','blue red\n');}
export function buildStructureSimulations(){return [listWalk(),listInsert(),listReverse(),listRemove(),tree('prefix'),tree('infix'),tree('suffix'),treeSearch(),argvSort()];}
